ADM = '00000000-0000-0000-0000-00000000000a'
def como(quem, q):
    r = banco(f"set role authenticated; select set_config('request.jwt.claim.sub', '{quem}', false); {q}").split('\n')
    return '\n'.join(r[2:]) if r[0] == 'SET' else '\n'.join(r)
def falha(quem, q):
    try: como(quem, q); return ''
    except RuntimeError as e: return str(e)
